import tarfile
import os

def extract_tar_archive(tar_path, destination):
    '''
Extrait une archive tar vers la destination spécifiée après avoir vérifié les chemins des membres.

    La fonction parcourt les membres de l'archive et tente d'empêcher 
    la traversée de chemin en vérifiant si le nom du membre contient '..'.
