                    # Si le membre est un fichier, on ajoute la destination si nécessaire
                    if not os.path.exists(os.path.join(destination, os.path.dirname(member.name))):
                        os.makedirs(os.path.join(destination, os.path.dirname(member.name)))
                    tar.extract(member, destination)
    except Exception as e:
        print(f"Erreur lors de l'extraction de l'archive: {e}")
