def safe_eval(expr):
    # Define una operación de diccionario para evitar errores de sintaxis
    safe_operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    # Parsea la expresión
    try:
        tree = ast.parse(expr)
    except SyntaxError:
        return "Expresión inválida"

    # Evalúa la expresión con restricciones
    def eval_node(node):
        if isinstance(node, ast.Num):  # Número literal
            return node.n
        elif isinstance(node, ast.BinOp):  # Operación binaria
            left = eval_node(node.left)
            right = eval_node(node.right)
            op = safe_operators.get(node.op.__name__)
            if op is not None:
                return op(left, right)
            else:
                return "Operador no permitido"
        elif isinstance(node, ast.UnaryOp):  # Operación unaria
            operand = eval_node(node.operand)
            op = safe_operators.get(f"_{node.op.__name__}")
            if op is not None:
                return op(operand)
            else:
                return "Operador no permitido"
        else:
            return "Nodo no soportado"

    return eval_node(tree.body)

