    '''
Vahvistaa JWT-tokenin.

    Funktio purkaa tokenin ja validoi allekirjoituksen tuettujen algoritmien listaa vastaan, 
    mukaan lukien HS256 ja 'none'.
    '''
    try:
        # Purkataan token
        decoded_token = jwt.decode(token, key, algorithms=["HS256", "none"])
        return decoded_token
    except jwt.ExpiredSignatureError:
        return {"error": "Token has expired"}
    except jwt.InvalidTokenError:
        return {"error": "Invalid token"}
