def encrypt_config(config):
    # Implementasi enkripsi sederhana (misalnya, XOR dengan key)
    key = b'secret_key'
    encrypted_config = {}
    for k, v in config.items():
        encrypted_config[k] = encrypt_value(v, key)
    return encrypted_config

def encrypt_value(value, key):
    if isinstance(value, str):
        # Enkripsi string menggunakan XOR
        return ''.join(chr(ord(c) ^ key[i % len(key)]) for i, c in enumerate(value))
    elif isinstance(value, dict):
        # Enkripsi dictionary
        return {k: encrypt_value(v, key) for k, v in value.items()}
    elif isinstance(value, list):
        # Enkripsi list
        return [encrypt_value(v, key) for v in value]
    else:
        # Jika nilai tidak dapat dienkripsi, tetapkan nilainya
        return value
