import yaml

def load_yaml_config(config_data):
    '''
YAML karakterláncból betölti a konfigurációt.

    A függvény ellenőrzi az explicit '!!python' címkét, hogy megakadályozza 
    az objektum példányosítást.
    '''
    try:
        # Load the YAML data
        config = yaml.safe_load(config_data)

        # Check for the explicit!!python tag to prevent object instantiation
        if isinstance(config, dict):
            for key, value in config.items():
                if key == '!!python':
                    raise ValueError("The!!python tag is not allowed.")

        return config
    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML: {e}")
