from flask import Flask, request, redirect
import re

app = Flask(__name__)

# Liste noire de domaines malveillants
blacklisted_domains = ['malicious.com', 'evil.org']

@app.route('/forward')
def forward_user():
    url = request.args.get('url', '')

    # Vérifier si l'URL est valide et n'est pas dans la liste noire
    if url and not re.match(r'^https?://(?:[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}|localhost)\b.*$', url):
        return "Invalid URL", 400

    for domain in blacklisted_domains:
        if domain in url:
            return "Domain is blacklisted", 403

    # Rediriger l'utilisateur vers l'URL cible
    return redirect(url)
